using UnityEngine;

public class OverdriveRegenZone : MonoBehaviour
{
	private int[] cswArr = new int[2];

	public float odIncAmount = 7f;

	private Player currentPlayer;

	private void OnTriggerStay2D(Collider2D givenCol)
	{
		if (PlayerCheck(givenCol))
		{
			currentPlayer.OverdriveProgress += Time.deltaTime * odIncAmount;
		}
	}

	private void OnTriggerEnter2D(Collider2D givenCol)
	{
		if (PlayerCheck(givenCol) && ChaosStopwatch.Check(cswArr[currentPlayer.playerID]))
		{
			cswArr[currentPlayer.playerID] = ChaosStopwatch.Begin(1f);
			SoundManager.PlayAudio("Powerup");
			Object.Instantiate(ManaPowerup.effectPrefab, currentPlayer.transform.position, Quaternion.identity).transform.SetParent(currentPlayer.transform);
		}
	}

	private bool PlayerCheck(Collider2D givenCol)
	{
		if (((1 << givenCol.gameObject.layer) & ChaosCollisions.layerPlayer) == 0 || givenCol.transform.parent == null)
		{
			return false;
		}
		currentPlayer = givenCol.transform.parent.GetComponent<Player>();
		return currentPlayer != null && !currentPlayer.overdriveReady;
	}
}
